var t=[{title:`Forma fizică generală`,text:`Scopul este o capacitate largă și sănătatea: antrenament cu rezistență pentru principalele tipare de mișcare, activitate aerobă regulată și puțină mobilitate și lucru de echilibru. Sesiunile pot folosi intervale moderate de repetări și orice echipament ai. Progresul poate însemna mai multă activitate săptămânală, mai multă energie în timpul zilei sau rezultate mai bune la flotări și la mers.`},{title:`Forța`,text:`Prioritatea este să produci mai multă forță în mișcările pe care le alegi. Un program de forță pune de obicei ridicările principale la începutul sesiunii, crește rezistența în timp și folosește pauze mai lungi, astfel încât tehnica și performanța să rămână bune. Sarcinile mai mari ajută cel mai mult la forța maximă, dar începătorii pot deveni mai puternici fără să-și testeze vreodată maximul.`},{title:`Condiția fizică`,text:`Prioritatea este să susții efortul, să te refaci între explozii de efort sau să îți îmbunătățești capacitatea cardiovasculară. Mersul constant, ciclismul, joggingul și intervalele sunt toate instrumente pentru asta. Cât lucru ușor și cât lucru greu faci depinde de nivelul tău de pregătire, de preferințe, de toleranța la impact și de echipament. Nu orice antrenament de condiție fizică trebuie să semene cu o cursă.`},{title:`Exemplu`,text:`Să zicem că ai trei sesiuni de 40 de minute pe săptămână. Pentru o bază de formă fizică generală, poți folosi două pentru rezistență full-body și una pentru cardio. Un bloc de forță ar putea păstra cele două sesiuni cu rezistență, ar adăuga o a treia sesiune de ridicări și ar păstra ceva activitate aerobă scurtă. Un bloc de condiție fizică s-ar putea muta spre lucrul aerob, păstrând cel puțin două sesiuni de forță pe săptămână când poți.`},{title:`Suprapunerea dintre obiective`,text:`Antrenamentul cu rezistență poate îmbunătăți rezistența musculară, iar cel aerob poate ajuta refacerea și sănătatea. Obiectivele diferă prin accent și se suprapun mult. Alege un obiectiv principal pentru patru până la opt săptămâni, apoi uită-te la rezultate înainte să îți schimbi prioritățile. Dacă schimbi după fiecare antrenament, progresul devine greu de judecat.`},{title:`Folosind TrainUp`,text:`Îți stabilești obiectivul (formă fizică generală, forță sau condiție fizică) în Profil. Indiferent de obiectiv, echipamentul, spațiul și limitările tale hotărăsc ce exerciții pot intra în plan.`}];var a=[{label:`Declarația de poziție ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Recomandările OMS privind activitatea fizică`,url:`https://www.who.int/europe/news-room/fact-sheets/item/physical-activity`}];var r={sections:t,sources:a};export{r as default,t as sections,a as sources};